<html dir="rtl" lang="ar">
<style>
    table, th, td{
      width: 100%;
      border: 1px solid black;
      border-collapse: collapse;
      text-align: center;
      margin-bottom: 20px;
      margin-top: 20px;
      font-size: {{ font_size }}px;
      table-layout:fixed;
    }
    img{
        width: 100%;
    }
    .header-details{
      margin-bottom: 0px;
      margin-top: 0x;
    }
    .header-details td{
      margin: auto;
      font-size: 14px;
    }
</style>
<body>
{% if letter_head %}
{{ letter_head.content }}
<hr>
{% endif %}
<table class="header-details" style="border:none;direction:rtl;">
    <tbody>
        <tr style="border:none;">
            <td colspan="2" style="border:none; width:100%; text-align:center; direction:rtl; white-space:nowrap;">
                <div style="display: flex; justify-content: space-around; align-items: center; width: 100%; flex-wrap: nowrap;">
                    {% if is_supplier %} 
                        <span style="margin: 0 20px; white-space: nowrap;">
                            {{ _("اسم المورد") }} : {{frappe.db.get_value("Supplier", header.party, "supplier_name") }}
                        </span>
                        {% if frappe.db.get_single_value("Agriculture Settings", "show_supplier_code_in_pdf") %}
                        <span style="margin: 0 20px; white-space: nowrap; direction:rtl;">
                            {{ _("كود المورد") }} : {{header.party }}
