        </td>
        <td style="direction: ltr;"> {% if sum.credit %} {{ frappe.format_value(sum.credit, {"fieldtype": "Currency"}) }} {% endif %}</td>
        <td style="direction: ltr;"> {% if sum.balance %} {{ frappe.format_value(sum.balance, {"fieldtype": "Currency"}) }} {% endif %}</td>
    </tr>
    {% endfor %}
    </tbody>
</table>
<hr>
{% endif %}

{% if items %}
<!--Items Details Table-->
<div>
    <h5> {{ _("تفاصيل الأصناف") }} </h5>
