        <th style="width: 15%"> {{ _("السلعة") }}</th>
        <th style="width: 8%"> {{ _("الكمية") }}</th>
        <th style="width:8%"> {{ _("السعر") }}</th>
        {% endif %}
        <th style="width: 8%"> {{ _("الإجمالى") }}</th>
    </tr>
